async function testAPI() {
  // Try the old Inference API with a simple text-generation model
  const response = await fetch('https://api-inference.huggingface.co/models/gpt2', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      inputs: 'Write a short story about a dragon and a wizard:',
      parameters: { max_new_tokens: 200 }
    })
  });
  const text = await response.text();
  return { status: response.status, body: text.substring(0, 1000) };
}
return testAPI().then(r => JSON.stringify(r));

async function tryInferenceAPI() {
  const endpoints = [
    'https://api-inference.huggingface.co/models/microsoft/DialoGPT-small',
    'https://api-inference.huggingface.co/models/gpt2',
    'https://router.huggingface.co/v1/chat/completions'
  ];
  const results = [];

  for (const url of endpoints) {
    try {
      const isOpenAI = url.includes('router');
      const opts = {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(isOpenAI 
          ? { model: 'meta-llama/Llama-3.2-3B-Instruct', messages: [{role: 'user', content: 'Write a 2 sentence story about a dragon and wizard'}] }
          : { inputs: 'A dragon and a wizard: ' }
        )
      };
      const r = await fetch(url, opts);
      const text = await r.text();
      results.push({ url, status: r.status, body: text.substring(0, 500) });
    } catch(e) {
      results.push({ url, error: e.message });
    }
  }
  return JSON.stringify(results, null, 2);
}
return tryInferenceAPI().then(r => r);

async function fillTextarea() {
  const textarea = document.querySelector('textarea[placeholder="Ask anything"]');
  if (!textarea) return { error: 'No textarea found' };

  // Set the value using native setter
  const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
  nativeSetter.call(textarea, 'Write a short story (about 3 paragraphs) about a dragon and a wizard who become friends.');
  textarea.dispatchEvent(new Event('input', { bubbles: true }));
  textarea.dispatchEvent(new Event('change', { bubbles: true }));

  return { value: textarea.value.substring(0, 100), found: true };
}
return fillTextarea().then(r => JSON.stringify(r));

async function findIframes() {
  const iframes = Array.from(document.querySelectorAll('iframe'));
  const info = iframes.map(f => ({ src: f.src, id: f.id, name: f.name }));

  // Also check all textareas anywhere
  const allTextareas = Array.from(document.querySelectorAll('textarea'));
  const textareaInfo = allTextareas.map(t => ({ placeholder: t.placeholder, parent: t.parentElement?.tagName }));

  return { iframes: info, textareas: textareaInfo, totalIframes: iframes.length, totalTextareas: allTextareas.length };
}
return findIframes().then(r => JSON.stringify(r));
